//! The ported document checks, one module per ticket script.
//!
//! Each module `c<id>` (file `c<id>.rs` or directory `c<id>/`) holds the
//! check of `checks/<id>.sh` as a function from [`Docs`] to [`Report`], and a
//! [`CheckSpec`] named `SPEC` that tells the equivalence harness how to
//! compare it with its script. The registry is generated by `build.rs` from
//! this directory: adding a port never edits a shared file.

use super::Docs;
use super::Report;

/// What the equivalence harness needs to know about one port.
#[derive(Debug)]
pub struct CheckSpec {
    /// The ticket id, as in `checks/<id>.sh`.
    pub id: &'static str,
    /// The port.
    pub run: fn(&Docs) -> Report,
    /// Environment the script must get under the harness: the override
    /// variables it honours, set to the exported copies, so it skips its
    /// repository-level cargo runs (those moved to
    /// `scripts/repo-state-checks.sh`). Paths are relative to the export
    /// root, which is the script's working directory.
    pub script_env: &'static [(&'static str, &'static str)],
    /// The documents and sections the mutation corpus edits.
    pub targets: &'static [Target],
    /// Words whose negation the corpus tries, beyond the defaults.
    pub keywords: &'static [&'static str],
    /// The verdict differences that are understood, with their reason.
    pub known_differences: &'static [KnownDifference],
}

/// A section of a document the corpus mutates.
#[derive(Debug, Clone, Copy)]
pub struct Target {
    /// Repository-relative path.
    pub file: &'static str,
    /// A heading pattern (regex): the first match's section is mutated;
    /// `None` for the whole file.
    pub heading: Option<&'static str>,
}

/// The class of an understood difference. "Port weaker" is never a class:
/// a mutation the script rejects and the port accepts fails the harness.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiffClass {
    /// The port rejects what the script accepted, for the stated reason.
    PortStricter,
    /// The script's verdict is wrong; the reason says how.
    ScriptWrong,
}

/// One understood difference: mutations whose label matches `label` (a
/// regex) and where the port's verdict is `port_fails`.
#[derive(Debug, Clone, Copy)]
pub struct KnownDifference {
    pub label: &'static str,
    pub port_fails: bool,
    pub class: DiffClass,
    pub reason: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/checks_registry.rs"));

/// The port of `id`, if one is registered.
pub fn find(id: &str) -> Option<&'static CheckSpec> {
    registry().into_iter().find(|s| s.id == id)
}
